I'll help you create a React component for a user profile card. Here's a clean implementation with TypeScript:

```tsx
interface UserProfileProps {
  name: string;
  email: string;
  avatarUrl?: string;
  role: string;
}

export function UserProfile({ name, email, avatarUrl, role }: UserProfileProps) {
  return (
    <div className="profile-card">
      <img src={avatarUrl || '/default-avatar.png'} alt={name} />
      <h2>{name}</h2>
      <p>{email}</p>
      <span className="role-badge">{role}</span>
    </div>
  );
}
```

Good idea! Here's the updated component with error handling:

```tsx
const [imgError, setImgError] = useState(false);

const handleImageError = () => setImgError(true);

<img 
  src={imgError ? '/default-avatar.png' : avatarUrl} 
  onError={handleImageError}
  alt={name} 
/>
```

This will gracefully fall back to a default avatar if the image fails to load.
